/**
 * Generate the browser-compatible UMD bundle from the canonical ES module.
 *
 * src/dsp.mjs is the single source of truth for every algorithm. This script
 * strips `export` keywords, wraps the code in a UMD factory and writes
 * src/dsp.cjs, which works both as `require('./src/dsp.cjs')` in Node tests
 * and as a plain <script> tag exposing window.DSP in the browser.
 *
 * Run: node scripts/build-bundle.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const dir = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(dir, '..');
const source = fs.readFileSync(path.join(root, 'src/dsp.mjs'), 'utf8');

const stripped = source
  .replace(/^export const /gm, 'const ')
  .replace(/^export function /gm, 'function ')
  .replace(/^export \{[^}]*\};?\s*$/gm, '')
  .replace(/^export default .*$/gm, '');

if (/\bexport\b/.test(stripped)) throw new Error('Unexpected export syntax remains');

// Only collect names declared at the top level (column 0, outside any block).
const lines = stripped.split('\n');
let depth = 0;
const apiNames = [];
for (const line of lines) {
  const match = /^(?:const|function)\s+([A-Za-z_$][\w$]*)/.exec(line);
  if (depth === 0 && match) apiNames.push(match[1]);
  for (const ch of line) {
    if (ch === '{') depth++;
    else if (ch === '}') depth--;
  }
}
if (depth !== 0) throw new Error('Unbalanced braces in source');

const required = ['fft', 'fftReal', 'ifftReal', 'biquadBode', 'designFilter', 'designFirLowpass',
  'exportWAV', 'exportExperimentJSON', 'exportBodeCSV', 'exportSpectrumCSV', 'renderPoleZeroSVG'];
for (const name of required) if (!apiNames.includes(name)) throw new Error('Missing API: ' + name);

const header = `/* Generated by scripts/build-bundle.mjs from src/dsp.mjs. Do not edit by hand. */
/* FFT Filter Bench browser bundle. Exposes window.DSP or module.exports. */
(function (root, factory) {
  'use strict';
  var api = factory();
  if (typeof module === 'object' && module.exports) module.exports = api;
  else root.DSP = api;
})(typeof globalThis !== 'undefined' ? globalThis : this, function () {
'use strict';
`;

const footer = `
return { ${apiNames.join(', ')} };
});
`;

const bundle = header + stripped + footer;
fs.writeFileSync(path.join(root, 'src/dsp.cjs'), bundle);
console.log(`Wrote src/dsp.cjs with ${apiNames.length} exports from src/dsp.mjs`);
